 public static function begin(string $title,string $active,array $user):void{$displayName=trim((string)($user['name']??$user['username']));$initial=mb_strtoupper(mb_substr($displayName,0,1));$photo=trim((string)($user['profile_photo']??''));$exists=$photo!==''&&is_file(BASE_PATH.'/public/'.ltrim($photo,'/'));$photoUrl=$exists?'../'.ltrim($photo,'/'):'';$roles=['ADMINISTRADOR'=>'Administrador','VENDEDOR'=>'Ventas','PROVEEDOR'=>'Proveedores','DEPOSITO'=>'Depósito','LOGISTICA'=>'Logística','CAJA'=>'Caja','ALMACEN'=>'Almacén','FINANZAS'=>'Finanzas','SISTEMAS'=>'Sistemas'];$role=$roles[(string)($user['role']??'')]??(string)($user['role']??'Usuario');$flash=self::pullFlash();?>
