n></form></div></div></div></aside><button class="sidebar-backdrop" type="button" data-sidebar-close></button><main class="dashboard-workspace"><header class="dashboard-topbar inventory-topbar"><button class="menu-button" type="button" data-sidebar-open><?=self::icon('menu')?></button><div><p class="topbar-kicker">Pagos y cobranzas</p><h1><?=e($title)?></h1></div></header><div class="dashboard-content inventory-content"><?php if($flash):?><div class="alert <?=$flash['type']==='success'?'alert-success':'alert-error'?> inventory-alert"><span><?=$flash['type']==='success'?'✓':'!'?></span><p><?=e($flash['message'])?></p></div><?php endif;?>
