 private static function pullFlash():?array{$f=$_SESSION['payment_flash']??null;unset($_SESSION['payment_flash']);return is_array($f)&&isset($f['type'],$f['message'])?$f:null;}
 private static function nav(string $href,string $key,string $label,string $active):string{$c=$key===$active?'nav-item is-active':'nav-item';return '<a class="'.$c.'" href="'.$href.'">'.self::icon($key).'<span>'.e($label).'</span></a>';}
 public static function icon(string $n):string{$icons=['home'=>'<path d="M3 11.5 12 4l9 7.5"/><path d="M5.5 10v10h13V10"/>','menu'=>'<path d="M4 6h16M4 12h16M4 18h16"/>','payments'=>'<path d="M4 6h15a2 2 0 0 1 2 2v11H4a2 2 0 0 1-2-2V6a3 3 0 0 1 3-3h13"/><path d="M16 11h5v4h-5a2 2 0 0 1 0-4Z"/>','account'=>'<path d="M4 5h16v14H4z"/><path d="M8 9h8M8 13h5"/>'];return '<svg viewBox="0 0 24 24" aria-hidden="true">'.($icons[$n]??$icons['payments']).'</svg>';}
